'use strict';
const L2={};window.L2=L2;
const PI2=Math.PI*2;
const G=(x,m,s,a)=>{const d=(x-m)/s;return a*Math.exp(-0.5*d*d);};
function rngOf(seed){let a=(seed>>>0)||1;return function(){a=(a+0x6D2B79F5)>>>0;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
function vnoise(r){const N=512,a=new Float32Array(N);for(let i=0;i<N;i++)a[i]=r()*2-1;return x=>{const i=Math.floor(x),f=x-i,u=f*f*(3-2*f),j=((i%N)+N)%N;return a[j]+(a[(j+1)%N]-a[j])*u;};}
const H=s=>esc(s);
const now=()=>performance.now();
const sd=()=>Math.floor(Math.random()*4294967295);

/* ---------- 파형 성분 ---------- */
const rOff=e=>e.m==='n'?0.45*e.d:e.m==='rbbb'?0.74*e.d:e.m==='vt'?0.33*e.d:0.32*e.d;
const tOn=e=>e.tw?e.t+e.tw.p-2.1*e.tw.s1:null;
const tOff=e=>e.tw?e.t+e.tw.p+2.3*e.tw.s2:null;
function qv(e,t){const x=t-e.t;if(x<-0.02||x>0.78)return 0;const d=e.d,a=e.a;let v=0;
 switch(e.m){
  case 'n':v=G(x,0.15*d,0.07*d,-0.08*a)+G(x,0.45*d,0.12*d,1.1*a)+G(x,0.76*d,0.1*d,-0.24*a);break;
  case 'w':v=G(x,0.32*d,0.16*d,1.0*a)+G(x,0.72*d,0.15*d,-0.5*a);break;
  case 'vt':v=G(x,0.33*d,0.19*d,1.15*a)+G(x,0.8*d,0.2*d,-0.72*a);break;
  case 'rbbb':v=G(x,0.2*d,0.08*d,0.32*a)+G(x,0.45*d,0.09*d,-0.42*a)+G(x,0.74*d,0.12*d,0.95*a);break;}
 const w=e.tw;if(w)v+=G(x,w.p,x<w.p?w.s1:w.s2,w.a);return v;}

/* ---------- 기저선 ---------- */
const BASE={
 fib:m=>{const r=m.rng,p=[r()*6,r()*6,r()*6],n=vnoise(r);return t=>0.034*Math.sin(PI2*6.1*t+p[0]+1.6*Math.sin(0.9*t))+0.03*Math.sin(PI2*7.7*t+p[1]+1.2*Math.sin(0.53*t+p[2]))+0.022*Math.sin(PI2*4.9*t+p[2]+Math.sin(1.3*t))+0.015*n(t*9);},
 flutter:()=>t=>{let ph=(t/0.2)%1;if(ph<0)ph+=1;return 0.92*(ph<0.72?0.09-0.30*(ph/0.72):-0.21+0.30*((ph-0.72)/0.28));},
 vf:m=>{const A=m.opt.v==='fine'?0.12:0.58,n1=vnoise(m.rng),n2=vnoise(m.rng),n3=vnoise(m.rng),n4=vnoise(m.rng);
  return t=>{const env=0.62+0.38*n1(t*0.9),ph=PI2*5.1*t+6*n2(t*0.75);return A*env*(0.66*Math.sin(ph)+0.4*Math.sin(1.7*ph+1.3+3*n3(t*1.3)))+A*0.26*n4(t*9);};},
 tdp:()=>t=>{const env=Math.sin(Math.PI*t/2.3),c=Math.cos(Math.PI*t/2.3),ph=PI2*3.9*t,W=p=>Math.sin(p)+0.25*Math.sin(2*p+0.8);return 0.98*env*W(ph)+0.16*c*W(ph+1.1);},
 flat:m=>{const n=vnoise(m.rng),n2=vnoise(m.rng);return t=>0.022*n(t*0.35)+0.006*n2(t*3);}
};

/* ---------- 리듬 모델 ---------- */
class Model{
 constructor(id,opt){this.id=id;this.opt=Object.assign({},opt||{});this.def=RD[id];this.rng=rngOf(this.opt.seed!=null?this.opt.seed:sd());
  this.els=[];this.genT=0;this.st={};this.lastQt=null;this.jit=vnoise(this.rng);this.baseFn=this.def.base?BASE[this.def.base](this):null;}
 ensure(t){let g=0,ch=false;while(this.genT<t+1.4&&g++<400){const a=this.genT,b=a+1;if(this.def.gen)this.def.gen(this,a,b);this.genT=b;ch=true;}
  if(ch){this.els.sort((x,y)=>x.t-y.t);if(this.els.length>700){const cut=t-70;this.els=this.els.filter(e=>e.t>cut);}}}
 lb(t){const E=this.els;let lo=0,hi=E.length;while(lo<hi){const m=(lo+hi)>>1;if(E[m].t<t)lo=m+1;else hi=m;}return lo;}
 range(a,b){if(b>this.genT-1.4)this.ensure(b);const E=this.els,o=[];for(let i=this.lb(a);i<E.length&&E[i].t<=b;i++)o.push(E[i]);return o;}
 v(t){if(t>this.genT-1.4)this.ensure(t);const E=this.els;let s=this.baseFn?this.baseFn(t):0;
  for(let i=this.lb(t-0.8);i<E.length;i++){const e=E[i];if(e.t>t+0.03)break;if(e.k==='P')s+=G(t-e.t,e.d/2,e.d/5.5,e.a);else if(e.k==='Q')s+=qv(e,t);}
  return s+0.008*this.jit(t*47);}
 P(t,o){o=o||{};const e={k:'P',t,d:o.d||0.1,a:o.a!=null?o.a:0.15,cond:o.cond!==false,tag:o.tag||null,q:null};this.els.push(e);return e;}
 Q(t,o){o=o||{};const m=o.m||'n',d=o.d||(m==='n'?0.08:m==='vt'?0.16:m==='rbbb'?0.13:0.15),a=o.a||1;
  const rr=this.lastQt!=null?clamp(t-this.lastQt,0.28,2):0.8;this.lastQt=t;const qt=o.qt||clamp(0.39*Math.sqrt(rr),0.25,0.46);let tw=null;
  if(m==='n'){const p=Math.max(d+0.1,qt-0.085);tw={p,a:o.ta!=null?o.ta:0.28,s1:Math.min(0.05,(p-d)/2.3),s2:0.036};}
  else if(m==='w'){const p=Math.max(d+0.12,qt-0.03);tw={p,a:-(o.ta!=null?o.ta:0.34)*a,s1:Math.min(0.06,(p-d)/2.2),s2:0.045};}
  else if(m==='rbbb'){const p=Math.max(d+0.1,qt-0.06);tw={p,a:0.14,s1:Math.min(0.05,(p-d)/2.3),s2:0.035};}
  const e={k:'Q',t,m,d,a,tw,p:o.p||null,tag:o.tag||null,sp:o.sp||null};if(o.p)o.p.q=e;this.els.push(e);return e;}
 S(t,cap){const e={k:'S',t,cap:!!cap};this.els.push(e);return e;}
}
function sinus(m,t1,c){const s=m.st;if(s.next==null)s.next=c.start!=null?c.start:0.22+m.rng()*0.3;
 while(s.next<t1){const pt=s.next,p=m.P(pt,{a:c.pa,d:c.pd});m.Q(pt+c.pr,{p,d:c.qd,a:c.qa,ta:c.ta});
  const rr=typeof c.rr==='function'?c.rr(m,pt):c.rr;s.next=pt+rr*(c.jit===0?1:1+(m.rng()-0.5)*0.03);}}

