let root=null,raf=0,lastTs=0,heart=null,condStrip=null,timerEl=null;
const st={cond:{mode:'NSR',speed:0.25},rate:{method:'300',step:0,n:20,irr:false,seed:1},sys:{id:'NSR',step:0,seed:1},cal:{task:'PR',rh:'rand',seed:1,a:0,b:0,show:false,res:null,score:{n:0,ok:0}},
 cmp:{a:'ST',b:'SVT',preset:0,hl:true,iv:false,wave:false},quiz:{cur:null,n:0,ok:0,streak:0,pool:null,done:false},speed:{on:false},acls:{cur:null,n:0,ok:0,done:false}};
const S={};// 탭별 스트립

function killStrips(){STRIPS.forEach(s=>{if(!s.cv.isConnected)s.destroy();});}
function loop(ts){if(curScreen!=='learn'){stop();return;}const dt=Math.min(0.1,(ts-(lastTs||ts))/1000);lastTs=ts;
 STRIPS.forEach(s=>{if(!s.cv.isConnected){s.destroy();return;}s.tick(dt);});
 if(heart&&condStrip&&condStrip.visible&&condStrip.w){const r=heart.update(condStrip.lanes[0].model,condStrip.t);phaseUI(r);}
 if(st.speed.on&&timerEl)timerEl.textContent=fmtT((now()-st.speed.t0)/1000);
 raf=requestAnimationFrame(loop);}
function start(){if(!raf){lastTs=0;raf=requestAnimationFrame(loop);}}
function stop(){if(raf)cancelAnimationFrame(raf);raf=0;STRIPS.forEach(s=>s.destroy());heart=null;condStrip=null;st.speed.on=false;}
const fmtT=s=>{const m=Math.floor(s/60),x=s-m*60;return String(m).padStart(2,'0')+':'+x.toFixed(1).padStart(4,'0');};

