function render(){
 root=$('#scr-learn');stop();
 const ov=overall(),mastered=QIDS.filter(id=>mastery(id)>=0.8).length,solved=Object.values(prog.r).reduce((a,r)=>a+(r.n||0),0);
 root.innerHTML='<div class="l2">'+
  '<div class="l2-head"><div class="l2-title"><span class="label">리듬 학습 랩</span><h2>심전도 리듬 학습</h2><p class="muted">전도계 원리에서 판독, 측정, ACLS 결정까지. 모든 파형은 실제 격자 비율(25 mm/초, 10 mm/mV)로 그립니다.</p></div>'+
  '<div class="l2-hstat" id="l2-hstat">'+hstat(ov,mastered,solved)+'</div></div>'+
  '<nav class="l2-tabs" role="tablist" aria-label="리듬 학습 메뉴">'+TABS.map(([k,l])=>'<button role="tab" data-l2="tab" data-v="'+k+'" class="'+(ui.tab===k?'on':'')+'" aria-selected="'+(ui.tab===k)+'">'+ico(k)+'<span>'+l+'</span></button>').join('')+'<i class="l2-ind"></i></nav>'+
  '<div class="l2-body" id="l2-body"></div></div>';
 renderTab();start();requestAnimationFrame(()=>{moveInd();topVar();});}
function hstat(ov,mastered,solved){return ring(ov,64,mColor(ov),Math.round(ov*100)+'%','big')+'<div><b>전체 숙련도</b><span>숙련 리듬 '+mastered+' / '+QIDS.length+'</span><span>푼 문제 '+solved+'</span></div>';}
function refreshHead(){const el=$('#l2-hstat');if(!el)return;const ov=overall();el.innerHTML=hstat(ov,QIDS.filter(id=>mastery(id)>=0.8).length,Object.values(prog.r).reduce((a,r)=>a+(r.n||0),0));}
function moveInd(){const nav=root&&root.querySelector('.l2-tabs');if(!nav)return;const b=nav.querySelector('button.on'),i=nav.querySelector('.l2-ind');if(!b||!i)return;i.style.width=b.offsetWidth+'px';i.style.transform='translateX('+b.offsetLeft+'px)';}
function topVar(){const tb=document.querySelector('.topbar');if(tb&&root)root.style.setProperty('--l2-top',(tb.offsetHeight||0)+'px');}
function setTab(k){if(!TABS.some(t=>t[0]===k))k='theory';ui.tab=k;saveUI();root.querySelectorAll('.l2-tabs button').forEach(b=>{const on=b.dataset.v===k;b.classList.toggle('on',on);b.setAttribute('aria-selected',on);});moveInd();
 const nb=root.querySelector('.l2-tabs button.on');if(nb&&nb.scrollIntoView)try{nb.scrollIntoView({block:'nearest',inline:'nearest'});}catch(e){}
 renderTab();}
