/* ---------- 카프노·심화 (SVG 도식) ---------- */
const f2=n=>(Math.round(n*100)/100).toString();
/* 심전도 SVG: 단위 mm (25 mm/초, 10 mm/mV) */
function ecgSvg(o){const W=o.secs*25,Hh=o.h,b=o.base,X=t=>t*25,Y=v=>b-v*10,dt=0.004;
 let gs='',gb='';for(let x=0;x<=W+1e-6;x++)(x%5?(s=>gs+=s):(s=>gb+=s))('M'+x+' 0V'+Hh);for(let y=0;y<=Hh+1e-6;y++)(y%5?(s=>gs+=s):(s=>gb+=s))('M0 '+y+'H'+W);
 const path=fn=>{let d='';for(let t=0;t<=o.secs+1e-9;t+=dt)d+=(d?'L':'M')+f2(X(t))+' '+f2(Y(fn(t)));return d;};
 let a='';(o.ann||[]).forEach(n=>{const c=n.c||COL.ink;
  if(n.k==='brk'){const x0=X(n.t0),x1=X(n.t1),y=Y(n.v);a+='<path class="kbk" style="stroke:'+c+'" d="M'+f2(x0)+' '+f2(y-1)+'V'+f2(y+1)+'M'+f2(x0)+' '+f2(y)+'H'+f2(x1)+'M'+f2(x1)+' '+f2(y-1)+'V'+f2(y+1)+'"/><text x="'+f2((x0+x1)/2)+'" y="'+f2(y+(n.up?-1.6:3.6))+'" text-anchor="middle" fill="'+c+'">'+H(n.s)+'</text>';}
  else if(n.k==='ring'){a+='<ellipse class="krg" style="stroke:'+c+'" cx="'+f2(X(n.t))+'" cy="'+f2(Y(n.v))+'" rx="'+(n.rx||2.6)+'" ry="'+(n.ry||2.6)+'"/>';}
  else{a+='<text x="'+f2(X(n.t))+'" y="'+f2(Y(n.v))+'" text-anchor="'+(n.an||'middle')+'" fill="'+c+'">'+H(n.s)+'</text>';}});
 const sp=(o.spikes||[]).map(t=>'<path class="ksp" d="M'+f2(X(t))+' '+f2(b+1)+'V'+f2(b-14)+'"/>').join('');
 return '<svg class="l2-xsv l2-xecg" viewBox="0 0 '+W+' '+Hh+'" role="img" aria-label="'+H(o.label||'심전도 도식')+'"><rect width="'+W+'" height="'+Hh+'" fill="'+PAPER.bg+'"/><path class="kgs" d="'+gs+'"/><path class="kgb" d="'+gb+'"/>'+
  (o.ref?'<path class="kref" d="'+path(o.ref)+'"/>':'')+'<path class="ktrg" d="'+path(o.fn)+'"/><path class="ktr" d="'+path(o.fn)+'"/>'+sp+'<g class="kan">'+a+'</g></svg>';}
/* 고칼륨혈증 단계별 파형 (II 유도 비슷한 도식) */
function beatAt(t,rr,t0){const k=Math.floor((t-t0)/rr);let s=0;for(const j of [k-1,k,k+1]){const x=t-(t0+j*rr);if(x>-0.3&&x<0.9)s+=this(x);}return s;}
const HKB={
 n:x=>G(x,0.05,0.018,0.15)+G(x,0.172,0.006,-0.08)+G(x,0.196,0.01,1.1)+G(x,0.221,0.008,-0.24)+G(x,0.46,x<0.46?0.05:0.035,0.28),
 t:x=>G(x,0.05,0.018,0.15)+G(x,0.172,0.006,-0.08)+G(x,0.196,0.01,1.05)+G(x,0.221,0.008,-0.26)+G(x,0.41,x<0.41?0.042:0.036,0.78),
 p:x=>G(x,0.06,0.032,0.06)+G(x,0.275,0.008,-0.06)+G(x,0.303,0.015,0.95)+G(x,0.338,0.012,-0.3)+G(x,0.55,x<0.55?0.032:0.028,0.78),
 w:x=>G(x,0.1,0.038,0.8)+G(x,0.2,0.036,-0.42)+G(x,0.37,x<0.37?0.045:0.04,0.66)
};
const hk=(k,rr,t0)=>t=>beatAt.call(HKB[k],t,rr,t0);
const sineK=t=>{const ph=PI2*t/0.6;return 0.82*Math.sin(ph)+0.1*Math.sin(2*ph+0.6);};
/* 경피 조율 */
const tcpNo=t=>{let s=0;for(let k=0;k<7;k++){const x=t-(0.12+k*0.72);if(x>-0.1&&x<0.3)s+=G(x,0.05,0.018,0.13);}return s;};
const tcpCap=t=>{let s=0;for(let k=-1;k<6;k++){const x=t-(0.3+k*0.857+0.012);if(x>-0.1&&x<0.8)s+=G(x,0.07,0.032,1.0)+G(x,0.16,0.03,-0.38)+G(x,0.38,0.065,-0.42);}return s;};
const TCPS=Array.from({length:5},(_,k)=>0.3+k*0.857);
/* 카프노그램 SVG: 가로 초, 세로 mmHg (0–50) */
function capSvg(o){const VW=320,VH=132,x0=34,x1=312,yT=12,yB=112,dur=o.dur||25,sx=(x1-x0)/dur,sy=(yB-yT)/50,X=t=>x0+t*sx,Y=v=>yB-v*sy;
 const R=0.32,E=o.E||2.6,F=0.28,val=t=>{let v=0;o.br.forEach((b,i)=>{const x=t-b,h=o.H[i];if(x<0||x>E+F)return;let y;if(x<R){const u=x/R;y=h*(1-Math.pow(1-u,2.4));}else if(x<E)y=h*(0.92+0.08*(x-R)/(E-R));else y=h*(1-(x-E)/F);v=Math.max(v,y);});
  if(o.rip&&v>1.5)v+=1.1*Math.sin(PI2*1.83*t);return Math.max(0,v);};
 let d='';for(let t=0;t<=dur+1e-9;t+=0.02)d+=(d?'L':'M')+f2(X(t))+' '+f2(Y(val(t)));
 let g='';for(let m=0;m<=50;m+=10)g+='<path class="kcg'+(m===0?' kz':'')+'" d="M'+x0+' '+f2(Y(m))+'H'+x1+'"/><text class="kcl" x="'+(x0-4)+'" y="'+f2(Y(m)+2.4)+'" text-anchor="end">'+m+'</text>';
 const bands=(o.bands||[]).map(b=>'<rect class="kcb" x="'+x0+'" y="'+f2(Y(b.b))+'" width="'+(x1-x0)+'" height="'+f2((b.b-b.a)*sy)+'" style="fill:'+b.c+'"/>'+(b.s?'<text class="kct" x="'+(x1-3)+'" y="'+f2(Y(b.b)+8)+'" text-anchor="end" fill="'+b.c.replace(/[\d.]+\)$/,'1)')+'">'+H(b.s)+'</text>':'')).join('');
 const lines=(o.lines||[]).map(l=>'<path class="kcth" style="stroke:'+l.c+'" d="M'+x0+' '+f2(Y(l.v))+'H'+x1+'"/>').join('');
 const ann=(o.ann||[]).map(n=>n.k==='dot'?'<circle cx="'+f2(X(n.t))+'" cy="'+f2(Y(n.v))+'" r="2.6" fill="'+(n.c||COL.ink)+'"/>':n.k==='arr'?'<path class="kcar" style="stroke:'+(n.c||COL.ink)+'" d="M'+f2(X(n.t))+' '+f2(Y(n.v0))+'L'+f2(X(n.t))+' '+f2(Y(n.v1))+'M'+f2(X(n.t)-3)+' '+f2(Y(n.v1)+4)+'L'+f2(X(n.t))+' '+f2(Y(n.v1))+'L'+f2(X(n.t)+3)+' '+f2(Y(n.v1)+4)+'"/>':
  '<text class="kct" x="'+f2(X(n.t))+'" y="'+f2(Y(n.v))+'" text-anchor="'+(n.an||'middle')+'" fill="'+(n.c||COL.ink)+'">'+H(n.s)+'</text>').join('');
 return '<svg class="l2-xsv l2-xcap" viewBox="0 0 '+VW+' '+VH+'" role="img" aria-label="'+H(o.label||'카프노그램 도식')+'"><rect width="'+VW+'" height="'+VH+'" rx="6" fill="#0a0f12"/>'+bands+g+lines+
  '<text class="kcl" x="'+(x0+4)+'" y="8" text-anchor="start">mmHg</text><text class="kcl" x="'+x1+'" y="'+(VH-6)+'" text-anchor="end">시간 → (호흡 6초마다 1회)</text>'+
  '<path class="kcf" d="'+d+'L'+x1+' '+yB+'L'+x0+' '+yB+'Z"/><path class="kcw" d="'+d+'"/>'+ann+'</svg>';}
