function advHTML(){
 const cap=[
  {c:'#41dd88',t:'양질의 CPR',v:'10–20 mmHg 이상',svg:capSvg({br:[0.6,6.6,12.6,18.6],H:[18,19,18,20],rip:true,bands:[{a:20,b:50,c:'rgba(65,221,136,.08)',s:'이상적 ≥20'}],lines:[{v:10,c:'#ff5f6d'}],ann:[{t:1.9,v:25,s:'압박 물결',c:'#cfe3ea'}],label:'양질의 CPR 중 카프노그램'}),
   p:'압박 깊이와 속도가 충분하고 중단이 짧으면 폐로 돌아오는 혈류가 늘어 EtCO₂가 10 mmHg 이상, 이상적으로 20 mmHg 이상을 보입니다. 고원 위의 잔물결은 가슴압박의 흔적입니다.'},
  {c:'#ff5f6d',t:'부적절한 CPR',v:'10 mmHg 미만',svg:capSvg({br:[0.6,6.6,12.6,18.6],H:[7,6,7.5,6.5],rip:true,lines:[{v:10,c:'#ff5f6d'}],ann:[{t:24.6,v:12.5,s:'10',an:'end',c:'#ff5f6d'},{t:3.8,v:15,s:'계속 10 아래',c:'#ff9aa3'}],label:'부적절한 CPR 중 카프노그램'}),
   p:'10 mmHg 미만이 이어지면 먼저 압박의 질을 고칩니다: 깊이 5–6 cm, 속도 100–120회/분, 완전한 이완, 2분마다 압박자 교대, 과환기 피하기. 지속되는 낮은 값은 나쁜 예후 신호지만 이 숫자 하나로 소생술 중단을 정하지 않습니다.'},
  {c:'#ffb648',t:'ROSC 시사',v:'갑자기 35–40 이상',svg:capSvg({br:[0.6,6.6,12.6,18.6],H:[15,16,39,42],rip:true,bands:[{a:35,b:45,c:'rgba(255,182,72,.10)'}],ann:[{k:'arr',t:11.0,v0:18,v1:36,c:'#ffb648'},{t:10.6,v:44,s:'급상승',an:'end',c:'#ffb648'}],label:'자발순환 회복을 시사하는 EtCO2 급상승'}),
   p:'압박을 계속하는 중에 EtCO₂가 갑자기 크게(대개 10 mmHg 이상) 뛰어 35–40 mmHg 이상이 되면 자발순환 회복(ROSC)을 시사합니다. 리듬과 맥박을 확인합니다. 탄산수소나트륨 투여 직후에도 잠깐 오를 수 있어 함께 해석합니다.'},
  {c:'#a993ff',t:'삽관 후 평탄선',v:'≈ 0 mmHg',svg:capSvg({br:[0.6,6.6,12.6,18.6],H:[5,2.2,0.6,0],ann:[{t:15.5,v:6,s:'파형 없음 — 튜브·회로 확인',c:'#c9b8ff'}],label:'기관 삽관 후 평탄한 카프노그램'}),
   p:'삽관 직후 파형이 없거나 처음 몇 번 작은 파형 뒤 0 근처로 평탄해지면 식도 삽관, 튜브 빠짐, 회로 분리·막힘을 먼저 의심하고 즉시 확인합니다(연결부 점검, 후두경으로 재확인, 필요하면 재삽관). 기관 안에 있으면 심정지 중에도 대개 작은 파형이라도 보입니다.'},
  {c:'#2fd3bf',t:'ROSC 후 정상 파형',v:'35–45 mmHg',svg:capSvg({br:[0.6,6.6,12.6,18.6],H:[38,39,38,39],E:3.6,bands:[{a:35,b:45,c:'rgba(47,211,191,.10)',s:'35–45'}],ann:[{t:6.4,v:24,s:'날숨 상승',an:'end',c:'#cfe3ea'},{t:8.6,v:46.5,s:'고원',c:'#cfe3ea'},{k:'dot',t:10.2,v:39,c:'#ffd54a'},{t:10.6,v:30,s:'EtCO₂',an:'start',c:'#ffd54a'},{t:10.8,v:3.5,s:'들숨 → 0',an:'start',c:'#cfe3ea'}],label:'자발순환 회복 후 정상 사각 카프노그램'}),
   p:'자발순환이 돌아오면 사각형 파형이 규칙적으로 이어지고 EtCO₂는 대개 35–45 mmHg입니다. 과환기로 수치를 끌어내리지 말고 PaCO₂ 35–45 mmHg 정상 범위를 목표로 환기합니다.'}];
 const capCards=cap.map(x=>'<div class="l2-xc" style="--c:'+x.c+'"><div class="l2-xch"><b>'+H(x.t)+'</b><span class="l2-xv">'+H(x.v)+'</span></div>'+x.svg+'<p>'+H(x.p)+'</p></div>').join('')+
  '<div class="l2-xc l2-xgoal" style="--c:#41dd88"><div class="l2-xch"><b>ROSC 후 초기 목표</b><span class="l2-xv">2025 AHA</span></div><ul>'+[['SpO₂','90–98%'],['평균동맥압 (MAP)','65 mmHg 이상'],['PaCO₂','35–45 mmHg'],['체온 조절','32–37.5 °C, 최소 36시간 (명령에 반응 없는 성인)']].map(([a,b])=>'<li><span>'+H(a)+'</span><b>'+H(b)+'</b></li>').join('')+'</ul><p>저산소와 과산소 모두 피하고, 저혈압을 막으며, 발열을 적극적으로 예방합니다. 12유도 심전도로 관상동맥 원인을 찾습니다.</p></div>';
 const HKS=[
  {n:1,c:'#ffd54a',t:'뾰족한 T파',p:'가장 먼저 보이는 변화입니다. T파가 높고 좁으며 좌우가 대칭인 텐트 모양이 됩니다.',svg:ecgSvg({secs:4,h:32,base:20,fn:hk('t',0.8,0.35),ref:hk('n',0.8,0.35),label:'고칼륨혈증 1단계 뾰족한 T파',ann:[{k:'ring',t:1.56,v:0.45,rx:2.8,ry:5,c:'#ffd54a'},{t:1.66,v:1.25,s:'좁고 높은 T',an:'start',c:'#ffd54a'}]})},
  {n:2,c:'#ffb648',t:'PR 연장 · P파 납작',p:'칼륨이 더 오르면 P파가 낮고 넓어지다 사라지고 PR이 길어집니다. QRS도 조금씩 넓어지기 시작합니다.',svg:ecgSvg({secs:4,h:32,base:20,fn:hk('p',0.8,0.35),label:'고칼륨혈증 2단계 PR 연장과 P파 평탄화',ann:[{k:'ring',t:1.21,v:0.04,rx:2.6,ry:1.8,c:'#ffb648'},{k:'brk',t0:1.15,t1:1.425,v:-0.55,s:'PR 연장',c:'#ffb648'},{t:1.21,v:0.42,s:'납작한 P',c:'#ffb648'}]})},
  {n:3,c:'#ff6b2c',t:'넓은 QRS',p:'QRS가 넓고 둔해지며 T파와 붙기 시작합니다. 서맥, 방실차단, 이탈 리듬이 함께 나타날 수 있습니다.',svg:ecgSvg({secs:4,h:32,base:19,fn:hk('w',0.95,0.3),label:'고칼륨혈증 3단계 넓은 QRS',ann:[{k:'brk',t0:1.22,t1:1.53,v:-0.7,s:'넓은 QRS',c:'#ff6b2c'}]})},
  {n:4,c:'#ff4f5e',t:'사인파',p:'QRS와 T파가 하나로 녹아 매끄러운 사인파가 됩니다. 곧 VF·무수축·PEA로 넘어갈 수 있는 심정지 직전 신호입니다.',svg:ecgSvg({secs:4,h:32,base:16,fn:sineK,label:'고칼륨혈증 4단계 사인파',ann:[{t:2.0,v:1.15,s:'QRS와 T가 합쳐진 물결',c:'#ff8a94'}]})}];
 const hkCards=HKS.map(x=>'<div class="l2-xc" style="--c:'+x.c+'"><div class="l2-xch"><span class="l2-xn">'+x.n+'</span><b>'+H(x.t)+'</b></div>'+x.svg+'<p>'+H(x.p)+'</p></div>').join('');
 return '<div class="l2-jump">'+[['capno','카프노그래피'],['hk','고칼륨혈증 심전도'],['pad','패드 위치'],['tcp','경피 조율 포획']].map(([k,l],i)=>'<button data-l2="jump" data-v="'+k+'"><b>0'+(i+1)+'</b>'+l+'</button>').join('')+'</div>'+
 '<section class="l2-card" id="l2-s-capno"><div class="l2-ch"><span class="l2-num">01</span><div><h3>카프노그래피 (EtCO₂)</h3><p class="muted">파형 카프노그래피는 날숨 끝 이산화탄소 분압을 숫자와 파형으로 보여 줍니다. CPR 중에는 폐로 가는 혈류, 곧 압박의 질을 반영하고, 기관 튜브 위치 확인과 감시에도 씁니다. 노란 선이 EtCO₂이고 전문기도 확보 후 6초마다 1회 환기하는 상황을 그렸습니다.</p></div></div>'+
 '<div class="l2-xgrid">'+capCards+'</div></section>'+
 '<section class="l2-card" id="l2-s-hk"><div class="l2-ch"><span class="l2-num">02</span><div><h3>고칼륨혈증 심전도 변화</h3><p class="muted">혈청 칼륨이 오를수록 대개 아래 순서로 진행합니다. 1단계의 회색 점선은 같은 박동의 정상 파형입니다.</p></div></div>'+
 '<div class="l2-xgrid">'+hkCards+'</div>'+
 '<div class="l2-xnote"><b>함께 기억할 점</b><ul><li>칼륨 수치와 심전도 변화가 꼭 비례하지 않아, 단계를 건너뛰고 갑자기 심정지가 올 수 있습니다.</li><li>심전도 변화가 있으면 응급입니다: 칼슘 정주로 심근막을 안정시키고, 인슐린·포도당 등으로 칼륨을 세포 안으로 옮기며, 이뇨제·투석으로 몸 밖으로 내보냅니다.</li><li>고칼륨혈증은 심정지의 가역적 원인(H와 T) 가운데 하나입니다. 신부전, 투석 환자, 칼륨 보존 약물 복용자에서 의심합니다.</li></ul></div></section>'+
 '<section class="l2-card" id="l2-s-pad"><div class="l2-ch"><span class="l2-num">03</span><div><h3>패드 위치</h3><p class="muted">전류가 심장을 가로지르도록 두 패드를 심장 양쪽에 붙입니다. 그림의 좌·우는 환자 기준입니다(앞모습에서는 환자의 왼쪽이 그림의 오른쪽).</p></div></div>'+
 '<div class="l2-xpads"><figure class="l2-xc" style="--c:#2fd3bf"><div class="l2-xch"><b>전외측 (앞–옆)</b><span class="l2-xv">가장 흔한 위치</span></div>'+padSvg('al')+'<ol class="l2-xleg"><li>오른쪽 빗장뼈 바로 아래, 흉골 오른쪽</li><li>왼쪽 겨드랑이 중간선, 젖꼭지 높이 아래쪽 옆가슴 (유방 조직 위는 피함)</li></ol></figure>'+
 '<figure class="l2-xc" style="--c:#ffb648"><div class="l2-xch"><b>삽입형 기기가 있을 때</b><span class="l2-xv">약 8 cm 거리</span></div>'+padSvg('dev')+'<ol class="l2-xleg"><li>심박조율기·ICD 바로 위(점선 ✕ 자리)를 피해 약 8 cm 떨어진 곳에 붙이거나 전후방 위치를 씁니다</li><li>옆 패드는 그대로</li></ol></figure>'+
 '<figure class="l2-xc l2-xwide" style="--c:#a993ff"><div class="l2-xch"><b>전후방 (앞–뒤)</b><span class="l2-xv">벡터 변경 · 기기 회피에 사용</span></div>'+padSvg('ap')+'<ol class="l2-xleg"><li>앞: 흉골 왼쪽, 심장 바로 앞 가슴</li><li>뒤: 척추 왼쪽, 왼쪽 어깨뼈 아래</li></ol></figure></div>'+
 '<div class="l2-xnote"><b>현장 요점</b><ul><li><b>불응성 VF</b>: 같은 위치로 충격을 반복해도 VF가 이어지면 패드 방향(벡터)을 바꾸는 것(전외측 ↔ 전후방)을 고려할 수 있습니다. 효과는 아직 확립되지 않았으며 CPR 중단을 늘리지 않도록 합니다.</li><li><b>삽입형 기기</b>: 패드를 기기 바로 위에 붙이지 않고 약 8 cm 떨어뜨립니다. 충격 뒤에는 기기 점검이 필요합니다.</li><li>붙이기 전: 가슴의 물기·땀을 닦고 약물 패치를 떼며, 털이 많으면 빠르게 제거합니다. 두 패드가 닿거나 겹치지 않게 합니다.</li></ul></div></section>'+
 '<section class="l2-card" id="l2-s-tcp"><div class="l2-ch"><span class="l2-num">04</span><div><h3>경피 심박조율 포획</h3><p class="muted">흰 세로선이 조율 스파이크입니다. 출력(mA)을 올려 가며 스파이크마다 넓은 QRS가 따라오는지 봅니다.</p></div></div>'+
 '<div class="l2-xgrid">'+
 '<div class="l2-xc" style="--c:#ff5f6d"><div class="l2-xch"><b>포획 없음</b><span class="l2-xv">스파이크만 보임</span></div>'+ecgSvg({secs:4,h:30,base:20,fn:tcpNo,spikes:TCPS,label:'경피 조율 포획 실패',ann:[{t:TCPS[1]+0.1,v:1.55,s:'스파이크',an:'start',c:'#e9f4ff'},{t:TCPS[2]+0.43,v:-0.55,s:'뒤에 QRS 없음',c:'#ff8a94'}]})+'<p>스파이크 뒤에 QRS가 없습니다(작은 P파는 바탕 리듬). 출력을 더 올리고 패드 접촉과 위치를 확인합니다.</p></div>'+
 '<div class="l2-xc" style="--c:#41dd88"><div class="l2-xch"><b>전기적 포획</b><span class="l2-xv">스파이크 → 넓은 QRS → T</span></div>'+ecgSvg({secs:4,h:30,base:18,fn:tcpCap,spikes:TCPS,label:'경피 조율 전기적 포획',ann:[{t:TCPS[1]+0.09,v:1.2,s:'넓은 QRS',an:'start',c:'#ff7a45'},{t:TCPS[2]+0.39,v:-0.85,s:'반대 방향 T',c:'#5cc8ff'}]})+'<p>스파이크마다 넓은 QRS와 반대 방향의 넓은 T파가 1:1로 따라옵니다. 출력이 크면 패드 인공 파형이 QRS처럼 보일 수 있어 T파까지 이어지는지 확인합니다.</p></div></div>'+
 '<div class="l2-xnote kwarn"><b>기계적 포획은 맥박으로</b><ul><li>전기적 포획을 본 뒤 반드시 <b>대퇴동맥</b>에서 맥박을 확인합니다. 경동맥은 조율 전류가 일으키는 근육 수축 때문에 맥박으로 착각하기 쉽습니다.</li><li>맥박 산소측정 파형, 혈압과 의식의 호전도 함께 봅니다. 출력은 포획 역치보다 조금 높게 유지하고, 통증이 크므로 진통·진정을 고려합니다.</li><li>맥박 있는 서맥에서 쓰는 치료입니다. 이미 심정지(무수축)인 성인에게 일상적인 조율은 권고되지 않습니다.</li></ul></div></section>';}

